        "refs": ["Q0000"]
      },
      "explanation_text": {
        "text": "Variable declarations are only allowed inside code blocks (delimited by curly braces) in Java; attempting to declare a variable outside a block causes a compilation error.",
        "refs": ["Q0000"]
      },
      "explanation_type": null
